WITH claimed AS ( SELECT id FROM media_jobs WHERE status = 'PENDING' AND dispatch_after IS NOT NULL AND dispatch_after <= #{now} AND type IN
#{item}
ORDER BY dispatch_after, id LIMIT #{batchSize} FOR UPDATE SKIP LOCKED ) UPDATE media_jobs j SET dispatch_token = #{batchToken}, dispatch_after = #{claimUntil}, updated_at = #{now} FROM claimed WHERE j.id = claimed.id RETURNING j.id, j.type

