mapper.select:
UPDATE media_jobs SET status = 'PENDING', available_at = #{nextAvailableAt}, dispatch_after = #{nextAvailableAt}, lease_until = NULL, dispatch_token = NULL, dispatched_at = NULL, failure_code = #{failureCode}, updated_at = #{now} WHERE status = 'RUNNING' AND attempt_count = #{expectedAttemptCount} AND lease_until IS NOT NULL AND lease_until <= #{now} AND id IN
#{jobId}
RETURNING id

UPDATE media_jobs SET status = 'FAILED', lease_until = NULL, dispatch_after = NULL, dispatch_token = NULL, failure_code = #{failureCode}, updated_at = #{now} WHERE status = 'RUNNING' AND lease_until IS NOT NULL AND lease_until <= #{now} AND id IN
#{jobId}
RETURNING id

UPDATE media_jobs
SET status = 'RUNNING',
    attempt_count = attempt_count + 1,
    lease_until = #{leaseUntil},
    dispatched_at = COALESCE(dispatched_at, #{now}),
    dispatch_after = NULL,
    dispatch_token = NULL,
    updated_at = #{now}
WHERE id = #{jobId}
    AND type = #{expectedType}
    AND status = 'PENDING'
    AND available_at <= #{now}
RETURNING id, asset_id, type, status, attempt_count, available_at, lease_until, dispatch_after, dispatch_token, dispatched_at, failure_code, created_at, updated_at

