UPDATE media_jobs
SET status = 'SUCCEEDED',
    lease_until = NULL,
    dispatch_after = NULL,
    dispatch_token = NULL,
    failure_code = NULL,
    updated_at = #{now}
WHERE id = #{jobId}
    AND status = 'RUNNING'
    AND attempt_count = #{expectedAttemptCount}
    AND lease_until > #{now}

UPDATE media_jobs
SET status = 'PENDING',
    available_at = #{nextAvailableAt},
    dispatch_after = #{nextAvailableAt},
    lease_until = NULL,
    dispatch_token = NULL,
    dispatched_at = NULL,
    failure_code = #{failureCode},
    updated_at = #{now}
WHERE id = #{jobId}
    AND status = 'RUNNING'
    AND attempt_count = #{expectedAttemptCount}
    AND lease_until > #{now}

UPDATE media_jobs
SET status = 'FAILED',
    lease_until = NULL,
    dispatch_after = NULL,
    dispatch_token = NULL,
    failure_code = #{failureCode},
    updated_at = #{now}
WHERE id = #{jobId}
    AND status = 'RUNNING'
    AND attempt_count = #{expectedAttemptCount}
    AND lease_until > #{now}
